// domain/notes-import.js.
export class ImportError extends Error {
  constructor(message, options) { super(message, options); this.name = "ImportError"; }
}

export function parseNotes(text) {
  let data;
  try {
    data = JSON.parse(text);
  } catch (err) {
    throw new ImportError("The file isn't valid JSON.", { cause: err });
  }
  if (!Array.isArray(data)) throw new ImportError("Expected a list of notes.");
  return data;
}

// ui/import-view.js: the boundary.
function onImport(text) {
  setBusy(true);
  try {
    const notes = parseNotes(text);
    saveNotes(notes);
    showStatus(`Imported ${notes.length} notes.`);
  } catch (err) {
    if (err instanceof ImportError) {
      showStatus(err.message);                                   // safe, short.
      console.warn("import failed", { length: text.length, cause: err.cause?.message });
    } else {
      showStatus("Something went wrong. Your notes were not changed.");
      throw err;                                                 // unknown bug: don't hide it.
    }
  } finally {
    setBusy(false);                                              // always runs.
  }
}
```

| Layer | Job |
|---|---|
| domain. | throw typed errors with cause. |
| network. | turn HTTP and network failures into typed errors. |
| UI boundary. | show a bounded message, log safe context, rethrow unknowns. |
| finally. | cleanup such as spinners and locks. |

